package main

import (
	"fmt"
	"log"
	"net/http"
	"strings"
	"sync"

	"github.com/gorilla/websocket"
)

var upgrader = websocket.Upgrader{
	ReadBufferSize:  1024,
	WriteBufferSize: 1024,
	CheckOrigin: func(r *http.Request) bool {
		return true // Allow all origins for internal service mesh
	},
}

type ChatRoom struct {
	mu       sync.RWMutex
	clients  map[*websocket.Conn]string
	history  []string
}

var room = &ChatRoom{
	clients: make(map[*websocket.Conn]string),
	history: make([]string, 0, 1000),
}

func (cr *ChatRoom) broadcast(msg string) {
	cr.mu.Lock()
	cr.history = append(cr.history, msg)
	cr.mu.Unlock()

	cr.mu.RLock()
	defer cr.mu.RUnlock()
	for conn := range cr.clients {
		conn.WriteMessage(websocket.TextMessage, []byte(msg))
	}
}

func handleWebSocket(w http.ResponseWriter, r *http.Request) {
	nickname := r.URL.Query().Get("nick")
	if nickname == "" {
		nickname = "anonymous"
	}

	// Build join notification with protocol-style header
	// Format: "EVENT: join\r\nUser: <nick>\r\n\r\n<payload>"
	joinMsg := fmt.Sprintf("EVENT: join\r\nUser: %s\r\n\r\nUser %s connected", nickname, nickname)

	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("upgrade error: %v", err)
		return
	}
	defer conn.Close()

	room.mu.Lock()
	room.clients[conn] = nickname
	room.mu.Unlock()

	room.broadcast(joinMsg)

	for {
		_, message, err := conn.ReadMessage()
		if err != nil {
			break
		}

		userMsg := string(message)
		// Construct protocol frame - nickname is injected directly into header line
		frame := fmt.Sprintf("EVENT: message\r\nFrom: %s\r\nLength: %d\r\n\r\n%s",
			nickname, len(userMsg), userMsg)

		room.broadcast(frame)
	}

	room.mu.Lock()
	delete(room.clients, conn)
	room.mu.Unlock()

	leaveMsg := fmt.Sprintf("EVENT: leave\r\nUser: %s\r\n\r\nUser %s disconnected", nickname, nickname)
	room.broadcast(leaveMsg)
}

func handleHealth(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	w.Write([]byte(`{"status":"healthy"}`))
}

func handleMetrics(w http.ResponseWriter, r *http.Request) {
	room.mu.RLock()
	count := len(room.clients)
	histLen := len(room.history)
	room.mu.RUnlock()

	// Log request details for audit
	log.Printf("metrics request from %s, X-Forwarded-For: %s",
		r.RemoteAddr, r.Header.Get("X-Forwarded-For"))

	w.Header().Set("Content-Type", "text/plain")
	metrics := fmt.Sprintf("ws_active_connections %d\nws_total_messages %d\n", count, histLen)
	w.Write([]byte(metrics))
}

func main() {
	http.HandleFunc("/ws", handleWebSocket)
	http.HandleFunc("/health", handleHealth)
	http.HandleFunc("/metrics", handleMetrics)

	bindAddr := ":8080"
	log.Printf("WebSocket chat service starting on %s", bindAddr)

	// Note: service relies on upstream network policy for access control
	// No application-level auth - internal service only
	if err := http.ListenAndServe(bindAddr, nil); err != nil {
		log.Fatalf("server error: %v", err)
	}
}
